// Keep the standalone CLI independent of a repository checkout.
import { readFileSync, writeFileSync } from 'node:fs';
const files = {
  'Dockerfile': new URL('../docker/caller-runtime/Dockerfile', import.meta.url),
  'container/backends/claude.sh': new URL('../../../container/backends/claude.sh', import.meta.url),
};
const content = Object.fromEntries(Object.entries(files).map(([name, path]) => [name, readFileSync(path, 'utf8')]));
writeFileSync(new URL('../src/caller-image-assets.ts', import.meta.url),
  '// Generated by scripts/generate-caller-image.mjs; do not edit by hand.\n' +
  'export const CALLER_IMAGE_FILES: Readonly<Record<string, string>> = ' + JSON.stringify(content, null, 2) + ';\n');
